var s=[{title:`Επιβραδύνετε σταδιακά`,text:`Μετά από ένα έντονο τρέξιμο ή μια βόλτα με ποδήλατο, περπατήστε ή κάντε πετάλι ήπια για λίγα λεπτά αντί να σταματάτε απότομα σε πλήρη προσπάθεια. Μετά από εργασία δύναμης, ένας σύντομος χαλαρός περίπατος και κανονική αναπνοή μπορεί να αισθάνονται καλά. Το απότομο σταμάτημα μπορεί μερικές φορές να σας προκαλέσει ζάλη, ειδικά μετά από μακρά, έντονη δραστηριότητα.`},{title:`Προαιρετική ήπια κινητικότητα`,text:`Μπορείτε να προσθέσετε άνετες κινήσεις για τη γάμπα, το ισχίο, το στήθος ή τον ώμο αν η ευκαμψία είναι ένας από τους στόχους σας ή απλώς σας αρέσουν. Στοχεύστε σε ήπια αίσθηση διάτασης και μην αναγκάζετε μεγάλα εύρη. Η βαθιά διάταση αμέσως μετά από μια κουραστική συνεδρία είναι προαιρετική, και η επώδυνη διάταση δουλεύει εναντίον σας.`},{title:`Τι δείχνουν τα στοιχεία`,text:`Η ελαφριά κίνηση μπορεί να κάνει πιο άνετα τα πρώτα λεπτά μετά την προπόνηση. Υπάρχουν λίγα στοιχεία ότι μια τυπική αποθέρμανση ή ρουτίνα διάτασης αποτρέπει αξιόπιστα τον πόνο της επόμενης μέρας (DOMS). Η σταδιακή πρόοδος, ο ύπνος και η αποκατάσταση εξακολουθούν να μετράνε. Η αποθέρμανση δεν θεραπεύει έναν τραυματισμό και δεν αντικαθιστά την ιατρική φροντίδα.`},{title:`Ταιριάξτε με τη συνεδρία`,text:`Ένας μέτριος περίπατος μπορεί να τελειώσει με ένα ή δύο ήπια λεπτά. Μετά από μια έντονη συνεδρία διαλειμμάτων, αφιερώστε αρκετά λεπτά σε ήπια κίνηση και αναπνοή μέχρι να αισθανθείτε σταθερά. Αν η ζάλη, η ασυνήθιστη δύσπνοια, ο πόνος στο στήθος ή η λιποθυμία δεν περνά, σταματήστε την προπόνηση και ζητήστε ιατρική βοήθεια.`}];var r=[{label:`NHS: ήπια άσκηση αποθέρμανσης`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`},{label:`ACE 2026: πρακτικές οδηγίες για τη διάταση`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`NHS: μυϊκός πόνος καθυστερημένης έναρξης`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`}];var i={sections:s,sources:r};export{i as default,s as sections,r as sources};